import React from 'react';
import { NavLink } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import { useTheme } from '../context/ThemeContext';

const links = [
  { to: '/dashboard', label: 'Dashboard', icon: 'bi-grid-1x2-fill' },
  { to: '/assessment', label: 'Assessment', icon: 'bi-clipboard2-pulse-fill' },
  { to: '/analytics', label: 'Analytics', icon: 'bi-graph-up-arrow' },
  { to: '/recommendations', label: 'Recommendations', icon: 'bi-lightbulb-fill' },
  { to: '/chat', label: 'AI Assistant', icon: 'bi-robot', special: true },
  { to: '/profile', label: 'Profile', icon: 'bi-person-circle' },
];

export default function Sidebar({ onNavigate }) {
  const { user, logout } = useAuth();
  const { theme, toggle } = useTheme();

  const linkClass = ({ isActive }) =>
    `nav-link ${isActive ? 'active' : ''}`;

  return (
    <aside className="sidebar-advanced">
      <div className="sidebar-brand">
        <div className="brand-logo">
          <i className="bi bi-heart-pulse-fill" />
        </div>
        <div>
          <div className="fw-bold text-white" style={{ fontFamily: 'var(--mw-font-display)' }}>MindWatch</div>
          <small style={{ color: 'rgba(255,255,255,0.5)', fontSize: '0.7rem' }}>AI Health Monitor</small>
        </div>
      </div>

      <nav className="sidebar-nav flex-grow-1">
        {links.map((l) => (
          <NavLink
            key={l.to}
            to={l.to}
            className={({ isActive }) => `${linkClass({ isActive })} ${l.special ? 'chat-link' : ''}`}
            onClick={onNavigate}
          >
            <i className={`bi ${l.icon}`} />
            {l.label}
            {l.special && <span className="ms-auto badge rounded-pill" style={{ background: '#22d3ee', fontSize: '0.6rem' }}>AI</span>}
          </NavLink>
        ))}
        {user?.isAdmin && (
          <NavLink to="/admin" className={linkClass} onClick={onNavigate}>
            <i className="bi bi-shield-lock-fill" />
            Admin Panel
          </NavLink>
        )}
      </nav>

      <div className="mt-auto pt-3 border-top border-secondary border-opacity-25">
        <div className="d-flex align-items-center gap-2 mb-3 px-1">
          <div className="brand-logo" style={{ width: 36, height: 36, fontSize: '0.9rem' }}>
            {user?.name?.[0]?.toUpperCase() || 'U'}
          </div>
          <div className="overflow-hidden">
            <div className="text-white small fw-semibold text-truncate">{user?.name}</div>
            <div className="text-white-50 text-truncate" style={{ fontSize: '0.7rem' }}>{user?.email}</div>
          </div>
        </div>
        <button className="btn btn-sm btn-outline-light w-100 mb-2" onClick={toggle}>
          <i className={`bi ${theme === 'light' ? 'bi-moon-stars' : 'bi-sun'}`} /> {theme === 'light' ? 'Dark' : 'Light'} Mode
        </button>
        <button className="btn btn-sm w-100" style={{ background: 'rgba(239,68,68,0.2)', color: '#fca5a5', border: '1px solid rgba(239,68,68,0.3)' }} onClick={logout}>
          <i className="bi bi-box-arrow-right" /> Logout
        </button>
      </div>
    </aside>
  );
}
